BEGIN;CREATE TABLE IF NOT EXISTS marketplace_integrity_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES work_assignments(id) ON DELETE RESTRICT,kind text NOT NULL CHECK(kind IN('suspected_bypass','contact_exchange','other')),evidence text NOT NULL CHECK(char_length(evidence) BETWEEN 1 AND 4000),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','needs_more_info','substantiated','unsubstantiated')),created_by_identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE RESTRICT,reviewed_by_identity_id uuid REFERENCES identities(id) ON DELETE RESTRICT,review_note text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);ALTER TABLE marketplace_integrity_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE marketplace_integrity_cases FORCE ROW LEVEL SECURITY;CREATE POLICY marketplace_integrity_cases_tenant ON marketplace_integrity_cases USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE ON marketplace_integrity_cases TO app_runtime;COMMIT;